-- Reference data: the places UDrive serves, and what a seat and a kilometre cost.
--
-- This is NOT demo content. The 35 destinations are real places in Azad Jammu
-- and Kashmir, and the rate card is what every fare quote is built from. With
-- either of them missing the customer app has an empty tourism catalogue and
-- cannot price a single ride.
--
-- WHY THIS FILE EXISTS AT ALL
--
-- "Add / refresh demo data" used to re-run two migration files as its seed:
-- 023 for the rate card and 010 for the destinations. A migration is written
-- against the schema of the moment it was written, and replaying one against
-- today's schema eventually breaks. It did: migration 025 later added
-- service_vehicle_rates.per_km_rate as NOT NULL with no default, and 023's
-- INSERT does not supply it. So the seed threw 23502 on its very first
-- statement, the whole transaction rolled back, and NOTHING was seeded --
-- not the rate card, not the destinations, not the demo hotels. The button
-- could not work, and it said so only as a 500.
--
-- So the seed no longer replays migrations. This file is data only, written
-- against the current schema, and it names every NOT NULL column it inserts.
-- Migrations own the schema; this owns the rows. Keep it that way.
--
-- Safe to run as often as you like: every statement is ON CONFLICT DO UPDATE.

-- ---------------------------------------------------------------------------
-- The vehicle rate card.
--
-- per_km_rate values are the ones migration 025 itself backfilled, so a
-- re-seed cannot quietly move a fare: bike 32, car 65, rickshaw 40,
-- coster 160.
-- ---------------------------------------------------------------------------
INSERT INTO udrive.service_vehicle_rates
    (service_type, vehicle_category, per_seat_rate, whole_vehicle_rate, per_km_rate)
VALUES
    ('City',           'Bike',      250, 250,   32),
    ('City',           'Car',       450, 1600,  65),
    ('City',           'Rickshaw',  300, 850,   40),
    ('City',           'Coster',    350, 7500,  160),
    ('PrivateVehicle', 'Bike',      300, 300,   32),
    ('PrivateVehicle', 'Car',       550, 2000,  65),
    ('PrivateVehicle', 'Rickshaw',  350, 1000,  40),
    ('PrivateVehicle', 'Coster',    450, 9000,  160)
ON CONFLICT (service_type, vehicle_category) DO UPDATE SET
    per_seat_rate      = EXCLUDED.per_seat_rate,
    whole_vehicle_rate = EXCLUDED.whole_vehicle_rate,
    per_km_rate        = EXCLUDED.per_km_rate,
    currency           = 'PKR',
    is_active          = true,
    updated_at         = now();

-- ---------------------------------------------------------------------------
-- The 35 destinations, lifted unchanged from migration 010.
--
-- Unchanged on purpose. These exact statements are already proven against the
-- live schema, and each one keys on the slug, so a re-seed refreshes a row
-- rather than duplicating it and never changes a destination's id -- which
-- matters, because tour packages point at these ids.
-- ---------------------------------------------------------------------------

