VALUES ('11000000-0000-0000-0000-000000000001','muzaffarabad','Muzaffarabad','مظفرآباد','Explore Muzaffarabad, one of Azad Jammu and Kashmir''s scenic tourism destinations. Check local weather and road conditions before departure.','مظفرآباد آزاد جموں و کشمیر کا خوبصورت سیاحتی مقام ہے۔ روانگی سے پہلے موسم اور سڑک کی صورتحال ضرور دیکھیں۔',ST_SetSRID(ST_MakePoint(73.4711,34.37),4326)::geography,'Muzaffarabad','March to November','Sedan / SUV','Good',92,88,'https://commons.wikimedia.org/wiki/Special:FilePath/Neelum%20River%20at%20Sharda%2C%20Neelum%20Valley.jpg?width=1200',true,now(),now())
ON CONFLICT (slug) DO UPDATE SET name_en=EXCLUDED.name_en,name_ur=EXCLUDED.name_ur,summary_en=EXCLUDED.summary_en,summary_ur=EXCLUDED.summary_ur,location=EXCLUDED.location,district=EXCLUDED.district,best_season=EXCLUDED.best_season,recommended_vehicle=EXCLUDED.recommended_vehicle,network_status=EXCLUDED.network_status,family_suitability_score=EXCLUDED.family_suitability_score,route_safety_score=EXCLUDED.route_safety_score,cover_image_url=EXCLUDED.cover_image_url,is_active=true,updated_at=now();
